    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(DECLARATIONS, limits.values().as_slice(), CEILING_VALUES, "SubscriptionKind")?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(DECLARATIONS, limits.values().as_slice(), CEILING_VALUES, "SubscriptionKind")?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Task(value) => { field::put(out, &[0], paths::SUBSCRIPTION_KIND_TAG)?; value.write(limits, out) },
            Self::Timer(value) => { field::put(out, &[1], paths::SUBSCRIPTION_KIND_TAG)?; value.write(limits, out) },
            Self::Topic(value) => { field::put(out, &[2], paths::SUBSCRIPTION_KIND_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::SUBSCRIPTION_KIND_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Task(TaskInterest::read(limits, reader)?)),
            1 => Ok(Self::Timer(TimerInterest::read(limits, reader)?)),
            2 => Ok(Self::Topic(TopicInterest::read(limits, reader)?)),
            3..=u8::MAX => Err(Problem { path: paths::SUBSCRIPTION_KIND_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
