// Type: End.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum End {
    Finished(EndFinished),
    FinishedWithFollowups(Box<EndFinishedWithFollowups>),
    Parked,
    Failed(EndFailed),
    Refused,
    Recheck,
    Exceeded(Exceeded),
    FailedWithReason(EndFailedWithReason),
    RefusedWithReason(EndRefusedWithReason),
    Suspended(Suspended),
}

// Record: End.
impl End {
    const SHAPE: &'static [skein_codec::bounds::Node] = &[
        skein_codec::bounds::Node::Named("EndFinished"),
        skein_codec::bounds::Node::Named("EndFinishedWithFollowups"),
        skein_codec::bounds::Node::Boxed { item: 1, size: size_of::<EndFinishedWithFollowups>() },
        skein_codec::bounds::Node::Scalar(0),
        skein_codec::bounds::Node::Named("EndFailed"),
        skein_codec::bounds::Node::Scalar(0),
        skein_codec::bounds::Node::Scalar(0),
        skein_codec::bounds::Node::Named("Exceeded"),
        skein_codec::bounds::Node::Named("EndFailedWithReason"),
        skein_codec::bounds::Node::Named("EndRefusedWithReason"),
        skein_codec::bounds::Node::Named("Suspended"),
        skein_codec::bounds::Node::Enum { variants: &[0, 2, 3, 4, 5, 6, 7, 8, 9, 10] },
    ];

    /// The record's encoded bound with every limit it reaches set to zero.
    pub const ENCODED_AT_ZERO: u64 = 278;
}

impl Record for End {
    type Limits = Limits;
    const TAIL: Path = paths::END_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(DECLARATIONS, limits.values().as_slice(), CEILING_VALUES, "End")?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(DECLARATIONS, limits.values().as_slice(), CEILING_VALUES, "End")?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Finished(value) => { field::put(out, &[0], paths::END_TAG)?; value.write(limits, out) },
            Self::FinishedWithFollowups(value) => { field::put(out, &[1], paths::END_TAG)?; value.write(limits, out) },
            Self::Parked => field::put(out, &[2], paths::END_TAG),
            Self::Failed(value) => { field::put(out, &[3], paths::END_TAG)?; value.write(limits, out) },
            Self::Refused => field::put(out, &[4], paths::END_TAG),
            Self::Recheck => field::put(out, &[5], paths::END_TAG),
            Self::Exceeded(value) => { field::put(out, &[6], paths::END_TAG)?; value.write(limits, out) },
            Self::FailedWithReason(value) => { field::put(out, &[7], paths::END_TAG)?; value.write(limits, out) },
            Self::RefusedWithReason(value) => { field::put(out, &[8], paths::END_TAG)?; value.write(limits, out) },
            Self::Suspended(value) => { field::put(out, &[9], paths::END_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::END_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Finished(EndFinished::read(limits, reader)?)),
            1 => Ok(Self::FinishedWithFollowups(Box::new(EndFinishedWithFollowups::read(limits, reader)?))),
            2 => Ok(Self::Parked),
            3 => Ok(Self::Failed(EndFailed::read(limits, reader)?)),
            4 => Ok(Self::Refused),
            5 => Ok(Self::Recheck),
            6 => Ok(Self::Exceeded(Exceeded::read(limits, reader)?)),
            7 => Ok(Self::FailedWithReason(EndFailedWithReason::read(limits, reader)?)),
            8 => Ok(Self::RefusedWithReason(EndRefusedWithReason::read(limits, reader)?)),
            9 => Ok(Self::Suspended(Suspended::read(limits, reader)?)),
            10..=u8::MAX => Err(Problem { path: paths::END_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

